function assertSpan(span) {
    if (!Number.isSafeInteger(span.startFrame) || !Number.isSafeInteger(span.endFrameExclusive)
        || span.startFrame < 0 || span.endFrameExclusive <= span.startFrame) {
        throw new Error("Frame span index entry is invalid");
    }
}
function build(entries) {
    if (entries.length === 0)
        return undefined;
    const centers = entries
        .map((entry) => entry.startFrame + (entry.endFrameExclusive - entry.startFrame) / 2)
        .sort((left, right) => left - right);
    const center = centers[Math.floor(centers.length / 2)];
    const left = [];
    const right = [];
    const overlaps = [];
    for (const entry of entries) {
        if (entry.endFrameExclusive <= center)
            left.push(entry);
        else if (entry.startFrame > center)
            right.push(entry);
        else
            overlaps.push(entry);
    }
    return Object.freeze({
        center,
        byStart: Object.freeze([...overlaps].sort((a, b) => a.startFrame - b.startFrame || a.endFrameExclusive - b.endFrameExclusive || a.serial - b.serial)),
        byEnd: Object.freeze([...overlaps].sort((a, b) => b.endFrameExclusive - a.endFrameExclusive || a.startFrame - b.startFrame || a.serial - b.serial)),
        left: build(left),
        right: build(right),
    });
}
function collectAt(node, frame, result) {
    if (node === undefined)
        return;
    if (frame < node.center) {
        for (const entry of node.byStart) {
            if (entry.startFrame > frame)
                break;
            result.push(entry);
        }
        collectAt(node.left, frame, result);
        return;
    }
    for (const entry of node.byEnd) {
        if (entry.endFrameExclusive <= frame)
            break;
        result.push(entry);
    }
    collectAt(node.right, frame, result);
}
function collectOverlapping(node, span, result) {
    if (node === undefined)
        return;
    for (const entry of node.byStart) {
        if (entry.startFrame >= span.endFrameExclusive)
            break;
        if (entry.endFrameExclusive > span.startFrame)
            result.push(entry);
    }
    if (span.startFrame < node.center)
        collectOverlapping(node.left, span, result);
    if (span.endFrameExclusive > node.center)
        collectOverlapping(node.right, span, result);
}
export class FrameSpanIndex {
    #root;
    constructor(values) {
        const entries = values.map((payload, serial) => {
            assertSpan(payload);
            return Object.freeze({
                startFrame: payload.startFrame,
                endFrameExclusive: payload.endFrameExclusive,
                serial,
                payload,
            });
        });
        this.#root = build(entries);
    }
    at(frame) {
        if (!Number.isSafeInteger(frame) || frame < 0)
            throw new Error("Frame span index query is invalid");
        const result = [];
        collectAt(this.#root, frame, result);
        return result.sort((left, right) => left.serial - right.serial).map((entry) => entry.payload);
    }
    overlapping(span) {
        assertSpan(span);
        const result = [];
        collectOverlapping(this.#root, span, result);
        return result.sort((left, right) => left.serial - right.serial).map((entry) => entry.payload);
    }
}
